# direct repeat search: exact repeats length 8..16 separated by 200..3000 bp
from collections import defaultdict
def dr_search(kmin,kmax,sepmin,sepmax):
    out=[]
    for k in range(kmin,kmax+1):
        idx=defaultdict(list)
        for i in range(n-k+1):
            idx[seq[i:i+k]].append(i)
        for kmer,pos in idx.items():
            if len(pos)>1:
                for a in range(len(pos)):
                    for b in range(a+1,len(pos)):
                        gap=pos[b]-(pos[a]+k)
                        if sepmin<=gap<=sepmax:
                            out.append((k,pos[a],pos[b],gap,kmer))
    # dedupe by keeping longest k per locus
    out.sort(key=lambda x:-x[0])
    res=[]
    used=[]
    for o in out:
        k,a,b,gap,kmer=o
        if any(abs(a-u[0])<k and abs(b-u[1])<k for u in used):
            continue
        used.append((a,b))
        res.append(o)
    return res

